import { ImageCache } from "#core/ui-next/utilities/image-cache.js";
import { StyleCache } from "#core/ui-next/utilities/style-cache.js";

class ComponentUtilitiesImpl {
	private imageCache = new ImageCache();
	private styleCache = new StyleCache();

	/**
	 * Loads stylesheets associated with a component
	 * @param urls A list of stylesheet urls to load
	 */
	public loadStyles(...urls: string[]) {
		return this.styleCache.loadStyles(...urls);
	}

	/**
	 * Preloads a list of images used by a component
	 * @param urls A list of image URLs to load
	 */
	public preloadImages(...urls: string[]) {
		return this.imageCache.loadImages(...urls);
	}
}

export const ComponentUtilities = new ComponentUtilitiesImpl();
